<script setup>
import{computed,onMounted,ref}from'vue';import{selfEvaluationApi as api}from'../../selfEvaluationApi'
const tasks=ref([]),task=ref(null),form=ref(null),warnings=ref([]),reminders=ref([]),message=ref(''),messageType=ref('success')
const openCount=computed(()=>warnings.value.filter(x=>x.status==='OPEN').length)
function notice(text,type='success'){message.value=text;messageType.value=type}
async function load(){try{[tasks.value,warnings.value,reminders.value]=await Promise.all([api.tasks(),api.warnings(),api.reminders()])}catch(e){notice(e.message,'error')}}
async function selectTask(id){if(!id){task.value=null;form.value=null;return}try{task.value=await api.task(id);form.value=null}catch(e){notice(e.message,'error')}}
async function selectForm(id){if(!id){form.value=null;return}try{form.value=await api.form(id)}catch(e){notice(e.message,'error')}}
async function requirement(x){const count=Number(prompt('必传材料数量',x.required_material_count));const allowed=prompt('允许格式（逗号分隔）',x.allowed_extensions);const keywords=prompt('命名关键词（逗号分隔）',x.naming_keywords||'');const due=prompt('截止日期 YYYY-MM-DD',x.due_date||'');try{await api.requirement(x.snapshot_id,{requiredMaterialCount:count,allowedExtensions:allowed,namingKeywords:keywords,dueDate:due});form.value=await api.form(form.value.id);notice('材料要求已更新')}catch(e){notice(e.message,'error')}}
async function run(){if(!task.value)return;try{const r=await api.runWarnings(task.value.id,form.value?.org_unit_id||'');notice(`规则检查完成：${r.warningCount}条预警`);await load()}catch(e){notice(e.message,'error')}}
async function process(x,status){const opinion=prompt('处理意见');if(!opinion)return;try{await api.processWarning(x.id,{status,opinion});notice('预警状态已更新');await load()}catch(e){notice(e.message,'error')}}
async function remind(x){try{await api.remind(x.id);notice('本地模拟提醒已记录（未发送真实短信）');await load()}catch(e){notice(e.message,'error')}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-warning">本页执行确定性“规则检查”，不使用AI。提醒仅写入本地日志，不发送真实短信。</div><div v-if="message" class="alert" :class="messageType==='error'?'alert-danger':'alert-success'">{{message}}</div><div class="stat-grid"><div class="stat-card"><div class="num">{{warnings.length}}</div><div class="label">历史预警</div></div><div class="stat-card"><div class="num red">{{openCount}}</div><div class="label">待处理</div></div><div class="stat-card"><div class="num">{{reminders.length}}</div><div class="label">模拟提醒</div></div></div>
<div class="card"><div class="card-header"><h3>⚙️ 材料要求与规则检查</h3><button class="btn btn-primary" :disabled="!task" @click="run">执行规则检查</button></div><div class="search-bar"><select @change="selectTask($event.target.value)"><option value="">选择任务</option><option v-for="x in tasks" :key="x.id" :value="x.id">{{x.task_name}}</option></select><select v-if="task" @change="selectForm($event.target.value)"><option value="">全部机构</option><option v-for="x in task.organizations" :key="x.id" :value="x.id">{{x.unit_name}}</option></select></div><table v-if="form"><thead><tr><th>指标</th><th>必传数</th><th>允许格式</th><th>命名关键词</th><th>截止日期</th><th>操作</th></tr></thead><tbody><tr v-for="x in form.entries" :key="x.id"><td>{{x.indicator_code}} {{x.indicator_name}}</td><td>{{x.required_material_count}}</td><td>{{x.allowed_extensions}}</td><td>{{x.naming_keywords||'-'}}</td><td>{{x.due_date||'-'}}</td><td><button class="btn btn-sm btn-outline" @click="requirement(x)">配置</button></td></tr></tbody></table></div>
<div class="card"><div class="card-header"><h3>🚨 完整性预警历史</h3></div><table><thead><tr><th>机构</th><th>指标</th><th>类型</th><th>信息</th><th>状态</th><th>检查时间</th><th>操作</th></tr></thead><tbody><tr v-if="!warnings.length"><td colspan="7">暂无规则预警</td></tr><tr v-for="x in warnings" :key="x.id"><td>{{x.unit_name}}</td><td>{{x.indicator_code}} {{x.indicator_name}}</td><td>{{x.warning_type}}</td><td>{{x.message}}</td><td>{{x.status}}</td><td>{{x.run_at}}</td><td><button class="btn btn-sm btn-outline" @click="process(x,'CONFIRMED')">确认</button> <button class="btn btn-sm btn-outline" @click="process(x,'IGNORED')">忽略</button> <button class="btn btn-sm btn-primary" @click="process(x,'RESOLVED')">解决</button> <button class="btn btn-sm btn-outline" @click="remind(x)">模拟提醒</button></td></tr></tbody></table></div>
</section></template>
